"use client"

import * as React from "react"

import { type Edit, type FormField } from "@/lib/retab"
import { cn } from "@/lib/utils"
import { useBBoxOverlay } from "@/hooks/use-retab"
import {
  RetabViewerShell,
  useViewerPhase,
} from "@/components/ui/retab-viewer-shell"

export interface EditViewerProps {
  edit: Edit
  /**
   * Render the page background for a given 1-based page number. Form fields on
   * that page are overlaid on top by normalized bounding box. Omit to show the
   * field list only.
   */
  renderPage?: (page: number) => React.ReactNode
  className?: string
}

export function EditViewer({ edit, renderPage, className }: EditViewerProps) {
  const fields = edit.output?.form_data ?? []
  const phase = useViewerPhase({
    status: edit.status,
    error: edit.error,
    hasOutput: fields.length > 0,
  })
  const color = edit.config?.color ?? "#000080"

  const pages = React.useMemo(() => {
    const set = new Set<number>()
    fields.forEach((f) => set.add(f.bbox.page))
    return [...set].sort((a, b) => a - b)
  }, [fields])

  const [activeKey, setActiveKey] = React.useState<string | null>(null)

  return (
    <RetabViewerShell
      title={edit.file?.filename ?? "Edit"}
      status={edit.status}
      error={edit.error}
      phase={phase}
      emptyMessage="No form fields were detected."
      className={className}
    >
      <div className="flex flex-col gap-4 p-4">
        {renderPage
          ? pages.map((page) => (
              <EditFieldOverlay
                key={page}
                fields={fields}
                page={page}
                color={color}
                activeKey={activeKey}
                onActivate={setActiveKey}
              >
                {renderPage(page)}
              </EditFieldOverlay>
            ))
          : null}

        <EditFieldList
          fields={fields}
          activeKey={activeKey}
          onActivate={setActiveKey}
        />
      </div>
    </RetabViewerShell>
  )
}

export interface EditFieldListProps {
  fields: FormField[]
  activeKey?: string | null
  onActivate?: (key: string | null) => void
}

export function EditFieldList({
  fields,
  activeKey,
  onActivate,
}: EditFieldListProps) {
  return (
    <div className="overflow-hidden rounded-lg border" data-slot="edit-field-list">
      <table className="w-full text-sm">
        <thead className="bg-muted/50 text-xs text-muted-foreground">
          <tr>
            <th className="px-3 py-2 text-left font-medium">Field</th>
            <th className="px-3 py-2 text-left font-medium">Value</th>
            <th className="px-3 py-2 text-left font-medium">Page</th>
          </tr>
        </thead>
        <tbody>
          {fields.map((field) => (
            <tr
              key={field.key}
              data-active={activeKey === field.key}
              onMouseEnter={() => onActivate?.(field.key)}
              onMouseLeave={() => onActivate?.(null)}
              className="border-t data-[active=true]:bg-muted/50"
            >
              <td className="px-3 py-2 align-top">
                <div className="font-medium">{field.key}</div>
                {field.description ? (
                  <div className="text-xs text-muted-foreground">
                    {field.description}
                  </div>
                ) : null}
              </td>
              <td className="px-3 py-2 align-top">
                <FieldValue field={field} />
              </td>
              <td className="px-3 py-2 align-top tabular-nums text-muted-foreground">
                {field.bbox.page}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

function FieldValue({ field }: { field: FormField }) {
  if (field.type === "checkbox") {
    const checked = field.value === "true" || field.value === "checked"
    return (
      <span className="inline-flex items-center gap-1.5">
        <span
          aria-hidden
          className={cn(
            "inline-flex size-4 items-center justify-center rounded border text-[10px]",
            checked
              ? "border-primary bg-primary text-primary-foreground"
              : "border-input"
          )}
        >
          {checked ? "✓" : ""}
        </span>
        <span className="text-muted-foreground">
          {checked ? "Checked" : "Unchecked"}
        </span>
      </span>
    )
  }
  return field.value ? (
    <span>{field.value}</span>
  ) : (
    <span className="text-muted-foreground italic">empty</span>
  )
}

/**
 * Headless overlay: positions form-field boxes over a relatively-sized page.
 * `children` is the page background (image, canvas, PDF page) — it defines the
 * box the normalized bboxes are mapped onto. Box geometry comes from
 * {@link useBBoxOverlay}.
 */
export interface EditFieldOverlayProps {
  fields: FormField[]
  page: number
  color?: string
  activeKey?: string | null
  onActivate?: (key: string | null) => void
  children: React.ReactNode
  className?: string
}

export function EditFieldOverlay({
  fields,
  page,
  color = "#000080",
  activeKey,
  onActivate,
  children,
  className,
}: EditFieldOverlayProps) {
  const rects = useBBoxOverlay(fields, page)
  return (
    <div
      data-slot="edit-field-overlay"
      className={cn("relative overflow-hidden rounded-md border", className)}
    >
      {children}
      {rects.map(({ field, style }) => {
        const active = activeKey === field.key
        return (
          <div
            key={field.key}
            title={`${field.key}: ${field.value ?? ""}`}
            onMouseEnter={() => onActivate?.(field.key)}
            onMouseLeave={() => onActivate?.(null)}
            className="rounded-[2px] transition-colors"
            style={{
              ...style,
              outline: `2px solid ${color}`,
              backgroundColor: active ? `${color}33` : `${color}1a`,
            }}
          />
        )
      })}
    </div>
  )
}

EditViewer.FieldList = EditFieldList
EditViewer.FieldOverlay = EditFieldOverlay

export { type Edit }
